+func isEmbeddingTokenIDs(input []interface{}) bool {
+	// JSON numbers decoded into interface{} are float64.
+	for _, item := range input {
+		id, ok := item.(float64)
+		if !ok || id < 0 || id != math.Trunc(id) {
+			return false
+		}
+	}
+	return true
